using System;
using System.Collections.Generic;
using System.Data;
using System.Drawing;
using System.Globalization;
using System.Linq;
using System.Text;
using System.Windows.Forms;
namespace CreatorSettlement {
public static class ClipboardTable {
 public static List<List<string>> Parse(string text){var rows=new List<List<string>>();var row=new List<string>();var cell=new StringBuilder();bool quote=false;for(int i=0;i<text.Length;i++){char c=text[i];if(c=='"'){if(quote&&i+1<text.Length&&text[i+1]=='"'){cell.Append('"');i++;}else if(quote||cell.Length==0)quote=!quote;else cell.Append(c);}else if(!quote&&(c=='\t'||c=='\r'||c=='\n')){row.Add(cell.ToString());cell.Length=0;if(c!='\t'){rows.Add(row);row=new List<string>();if(c=='\r'&&i+1<text.Length&&text[i+1]=='\n')i++;}}else cell.Append(c);}if(quote)throw new Exception("复制的内容引号不完整，请重新复制。");if(cell.Length>0||row.Count>0){row.Add(cell.ToString());rows.Add(row);}return rows;}
}
public sealed partial class MainWindow {
 sealed class CellWrite {public DataRow Row;public DataColumn Column;public object Value;}
 static DataRow BlankRow(DataTable table){var row=table.NewRow();foreach(DataColumn column in table.Columns)if(column.Expression=="")row[column]=column.DataType==typeof(decimal)?(object)DBNull.Value:"";if(table.Columns.Contains("收款类型(必填)")){row["收款类型(必填)"]="小额";row["打款对象类型(必填)"]="团长";row["团长比例"]="1";}return row;}
 void AddBlankRow(){Require();Commit();var table=CurrentTable();var row=BlankRow(table);RunChange("新增空白行",()=>{table.Rows.Add(row);model.Refresh();});CurrentFilterClear();var grid=CurrentGrid();var viewRow=grid.Rows.Cast<DataGridViewRow>().First(r=>((DataRowView)r.DataBoundItem).Row==row);string id=table==model.Check?"任务/方案ID":"任务ID";grid.CurrentCell=viewRow.Cells[id];grid.ClearSelection();grid.CurrentCell.Selected=true;status.Text="已新增空白行，直接填写即可；可按Ctrl+Z撤销。";}
 void PasteClipboard(){PasteText(Clipboard.GetText(TextDataFormat.UnicodeText));}
 void PasteText(string text){Require();Commit();var grid=CurrentGrid();if(grid.CurrentCell==null)throw new Exception("请先点击要粘贴的起始单元格。");var input=ClipboardTable.Parse(text);if(input.Count==0)return;var columns=grid.Columns.Cast<DataGridViewColumn>().Where(c=>c.Visible).OrderBy(c=>c.DisplayIndex).ToList();int firstColumn=columns.IndexOf(grid.CurrentCell.OwningColumn);int start=grid.CurrentCell.RowIndex;if(input.Any(r=>r.Count>columns.Count-firstColumn))throw new Exception("粘贴内容超出右侧列数，请换一个起始位置，或少复制几列。");var visible=grid.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow).Select(r=>((DataRowView)r.DataBoundItem).Row).ToList();var table=CurrentTable();var added=new List<DataRow>();var plan=new List<CellWrite>();for(int i=0;i<input.Count;i++){DataRow row=start+i<visible.Count?visible[start+i]:BlankRow(table);if(row.RowState==DataRowState.Detached)added.Add(row);for(int j=0;j<input[i].Count;j++){var column=columns[firstColumn+j];if(column.ReadOnly)continue;var dataColumn=table.Columns[column.DataPropertyName];object value=input[i][j];if(dataColumn.DataType==typeof(decimal)){decimal number;string numberText=input[i][j].Trim();if(numberText=="")value=DBNull.Value;else if(!Decimal.TryParse(numberText,NumberStyles.Number,CultureInfo.CurrentCulture,out number))throw new Exception("第"+(i+1)+"行的“"+column.HeaderText+"”不是有效数字，未粘贴任何内容。");else value=number;}plan.Add(new CellWrite{Row=row,Column=dataColumn,Value=value});}}if(plan.Count==0)throw new Exception("选择的位置是自动计算列，请粘贴到可填写的列。");RunChange("粘贴单元格",()=>{foreach(var row in added)table.Rows.Add(row);foreach(var write in plan)write.Row[write.Column]=write.Value;model.Refresh();});if(added.Count>0)CurrentFilterClear();else RefreshFilters();grid.ClearSelection();foreach(var row in grid.Rows.Cast<DataGridViewRow>()){var data=((DataRowView)row.DataBoundItem).Row;foreach(var write in plan.Where(p=>p.Row==data))row.Cells[write.Column.ColumnName].Selected=true;}status.Text="已粘贴"+input.Count+"行；自动计算列已保留，可撤销。";}
 void ClearSelectedCells(){Require();Commit();var grid=CurrentGrid();var cells=grid.SelectedCells.Cast<DataGridViewCell>().Where(c=>!c.ReadOnly).ToList();if(cells.Count==0)return;var writes=cells.Select(c=>new CellWrite{Row=((DataRowView)c.OwningRow.DataBoundItem).Row,Column=CurrentTable().Columns[c.OwningColumn.DataPropertyName],Value=c.ValueType==typeof(decimal)?(object)DBNull.Value:""}).ToList();RunChange("清空单元格",()=>{foreach(var write in writes)write.Row[write.Column]=write.Value;model.Refresh();});RefreshFilters();status.Text="已清空选中内容，可撤销。";}
 void FillDown(){Require();Commit();var grid=CurrentGrid();var cells=grid.SelectedCells.Cast<DataGridViewCell>().ToList();var writes=new List<CellWrite>();foreach(var group in cells.GroupBy(c=>c.ColumnIndex)){var ordered=group.OrderBy(c=>c.RowIndex).ToList();object value=ordered[0].Value??DBNull.Value;foreach(var cell in ordered.Skip(1).Where(c=>!c.ReadOnly))writes.Add(new CellWrite{Row=((DataRowView)cell.OwningRow.DataBoundItem).Row,Column=CurrentTable().Columns[cell.OwningColumn.DataPropertyName],Value=value});}if(writes.Count==0)return;RunChange("向下填充",()=>{foreach(var write in writes)write.Row[write.Column]=write.Value;model.Refresh();});RefreshFilters();status.Text="已用选区最上方的内容向下填充，可撤销。";}
 void SortCurrentColumn(DataGridView grid,string direction){if(model==null||grid.CurrentCell==null)return;Commit();var table=CurrentTable();string name=grid.CurrentCell.OwningColumn.DataPropertyName;table.DefaultView.Sort="["+name.Replace("]","\\]")+"] "+direction;}
 void AddExcelMenu(DataGridView grid){var menu=grid.ContextMenuStrip;menu.Items.Add(new ToolStripSeparator());Action<string,Action> add=(label,action)=>{var item=new ToolStripMenuItem(label);item.Click+=(o,e)=>Attempt(action);menu.Items.Add(item);};add("粘贴  Ctrl+V",PasteClipboard);add("清空内容  Delete",ClearSelectedCells);add("向下填充  Ctrl+D",FillDown);add("新增空白行",AddBlankRow);add("删除选中行",DeleteTableRows);add("按此列升序",()=>SortCurrentColumn(grid,"ASC"));add("按此列降序",()=>SortCurrentColumn(grid,"DESC"));int columnAnchor=-1,rowAnchor=-1;grid.RowHeadersVisible=true;grid.RowHeadersWidth=52;grid.RowHeadersWidthSizeMode=DataGridViewRowHeadersWidthSizeMode.DisableResizing;grid.CellPainting+=(o,e)=>{if(e.ColumnIndex==-1&&e.RowIndex>=0){e.PaintBackground(e.ClipBounds,true);TextRenderer.DrawText(e.Graphics,(e.RowIndex+1).ToString(),grid.Font,e.CellBounds,grid.ForeColor,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);e.Handled=true;}};grid.ColumnHeaderMouseClick+=(o,e)=>{if(grid.Rows.Count==0)return;if(e.Button==MouseButtons.Right)grid.CurrentCell=grid.Rows[0].Cells[e.ColumnIndex];bool shift=(ModifierKeys&Keys.Shift)!=0,ctrl=(ModifierKeys&Keys.Control)!=0;int from=shift&&columnAnchor>=0?Math.Min(columnAnchor,e.ColumnIndex):e.ColumnIndex;int to=shift&&columnAnchor>=0?Math.Max(columnAnchor,e.ColumnIndex):e.ColumnIndex;if(!ctrl)grid.ClearSelection();for(int i=from;i<=to;i++)if(grid.Columns[i].Visible)foreach(DataGridViewRow row in grid.Rows)row.Cells[i].Selected=true;columnAnchor=e.ColumnIndex;};grid.RowHeaderMouseClick+=(o,e)=>{bool shift=(ModifierKeys&Keys.Shift)!=0,ctrl=(ModifierKeys&Keys.Control)!=0;int from=shift&&rowAnchor>=0?Math.Min(rowAnchor,e.RowIndex):e.RowIndex;int to=shift&&rowAnchor>=0?Math.Max(rowAnchor,e.RowIndex):e.RowIndex;if(!ctrl)grid.ClearSelection();for(int i=from;i<=to;i++)foreach(DataGridViewCell cell in grid.Rows[i].Cells)if(cell.Visible)cell.Selected=true;rowAnchor=e.RowIndex;};grid.CellMouseDown+=(o,e)=>{if(e.RowIndex==-1&&e.ColumnIndex==-1)grid.SelectAll();};}
 bool ExcelShortcut(Keys keys){if(model==null)return false;var grid=CurrentGrid();if(!grid.ContainsFocus||grid.IsCurrentCellInEditMode)return false;if(keys==(Keys.Control|Keys.V)){Attempt(PasteClipboard);return true;}if(keys==Keys.Delete){Attempt(ClearSelectedCells);return true;}if(keys==(Keys.Control|Keys.D)){Attempt(FillDown);return true;}if(keys==(Keys.Control|Keys.A)){grid.SelectAll();return true;}if(keys==(Keys.Control|Keys.Add)||keys==(Keys.Control|Keys.Oemplus)){Attempt(AddBlankRow);return true;}if(keys==(Keys.Control|Keys.Subtract)||keys==(Keys.Control|Keys.OemMinus)){Attempt(DeleteTableRows);return true;}return false;}
}
}
